1	import { randomUUID } from "crypto";
2	import Anthropic from "@anthropic-ai/sdk";
3	import { computeCost } from "./costs";
4	import { appendAnalyticsEntry } from "@/app/lib/analytics/persist";
5	import { computeHash, getCachedResult, setCachedResult } from "./cache";
