241	async function streamOpenRouter(
242	  controller: ReadableStreamDefaultController<Uint8Array>,
243	  opts: StreamProviderOptions,
244	): Promise<void> {
245	  const start = Date.now();
246	
247	  const response = await fetch(OPENROUTER_API_URL, {
248	    method: "POST",
249	    headers: {
250	      "Content-Type": "application/json",
251	      Authorization: `Bearer ${opts.apiKey}`,
252	    },
253	    body: JSON.stringify({
254	      model: opts.model,
255	      stream: true,
256	      messages: [
257	        { role: "system", content: opts.systemPrompt },
258	        { role: "user", content: opts.userContent },
259	      ],
260	    }),
261	  });
262	
263	  if (!response.ok) {
264	    const errorBody = await response.text();
265	    throw errorWithDetails(`OpenRouter API error: ${response.status}`, errorBody);
266	  }
267	
268	  const reader = response.body?.getReader();
269	  if (!reader) throw new Error("OpenRouter response has no body");
270	
271	  const decoder = new TextDecoder();
272	  let buffer = "";
273	  let accumulated = "";
274	  let inputTokens = 0;
275	  let outputTokens = 0;
276	
277	  for (;;) {
278	    const { done, value } = await reader.read();
279	    if (done) break;
280	
281	    buffer += decoder.decode(value, { stream: true });
282	    const lines = buffer.split("\n");
283	    // Keep the last (potentially incomplete) line in the buffer
284	    buffer = lines.pop() ?? "";
285	
286	    for (const line of lines) {
287	      const trimmed = line.trim();
288	      if (!trimmed || trimmed.startsWith(":")) continue;
289	      if (!trimmed.startsWith("data: ")) continue;
290	
291	      const payload = trimmed.slice(6);
292	      if (payload === "[DONE]") continue;
293	
294	      try {
295	        const chunk = JSON.parse(payload);
296	        const delta = chunk.choices?.[0]?.delta?.content;
297	        if (delta) {
298	          accumulated += delta;
299	          controller.enqueue(sseEvent("token", { text: delta }));
300	        }
301	        // Extract usage from final chunk if present
302	        if (chunk.usage) {
303	          inputTokens = chunk.usage.prompt_tokens ?? inputTokens;
304	          outputTokens = chunk.usage.completion_tokens ?? outputTokens;
305	        }
306	      } catch { /* skip malformed SSE lines */ }
307	    }
308	  }
309	
310	  const latencyMs = Date.now() - start;
311	  const usage: LlmCallUsage = {
312	    provider: "openrouter",
313	    model: opts.model,
314	    inputTokens,
315	    outputTokens,
316	    costUsd: computeCost(opts.model, inputTokens, outputTokens),
317	    latencyMs,
318	  };
319	
320	  await recordAndCache(opts.endpoint, usage, accumulated, opts.cacheHash);
321	  controller.enqueue(sseEvent("done", { text: accumulated, usage }));
322	  controller.close();
323	}
