6	/**
7	 * Editing route for structured JSON artifacts (causal-graph, statistical-model, etc.).
8	 * Accepts the current JSON content, an instruction, and an optional text selection.
9	 * Returns the modified JSON in the same schema.
10	 */
11	
12	const SYSTEM_PROMPT_WHOLE = `You are an editing assistant for structured JSON artifacts. The user will give you a JSON document and an editing instruction. Apply the instruction to the JSON and return ONLY the modified JSON object — no commentary, no markdown fences, no explanation. Preserve the exact same schema (all required keys, correct types). Do not add or remove top-level keys.`;
13	
14	const SYSTEM_PROMPT_INLINE = `You are an editing assistant for structured JSON artifacts. The user will give you a JSON document and a selected portion of that JSON text. Apply the user's instruction ONLY to the selected portion and return ONLY the edited version of the selected text — no commentary, no markdown fences, no explanation. The result must be valid within the surrounding JSON context (e.g. properly quoted strings, valid numbers, etc.).`;
15	
16	function mockWholeResponse(content: string, instruction: string): string {
17	  return `${content.slice(0, -1)}\n  // mock edit: "${instruction.slice(0, 60)}"\n}`;
18	}
19	
20	function mockInlineResponse(selectionText: string, instruction: string): string {
21	  return `[mock: "${instruction.slice(0, 40)}" applied to "${selectionText.slice(0, 30)}"]`;
22	}
23	
24	export async function POST(request: NextRequest) {
25	  const { content, instruction, selection } = await request.json() as {
26	    content: string;
27	    instruction: string;
28	    selection?: { start: number; end: number; text: string };
29	  };
30	
31	  if (!content || !instruction) {
32	    return NextResponse.json(
33	      { error: "content and instruction are required" },
34	      { status: 400 },
35	    );
36	  }
37	
38	  const isInline = selection != null;
39	  const systemPrompt = isInline ? SYSTEM_PROMPT_INLINE : SYSTEM_PROMPT_WHOLE;
40	
41	  const userContent = isInline
42	    ? `JSON document:\n${content}\n\nSelected text (characters ${selection.start}–${selection.end}):\n${selection.text}\n\nInstruction: ${instruction}`
43	    : `JSON document:\n${content}\n\nInstruction: ${instruction}`;
44	
45	  try {
46	    const { text: responseText, usage } = await callLlm({
47	      endpoint: isInline ? "edit/artifact-inline" : "edit/artifact-whole",
48	      systemPrompt,
49	      userContent,
50	      maxTokens: 8192,
51	      openRouterModel: OPENROUTER_MODEL,
52	    });
53	
54	    if (usage.provider === "mock") {
55	      if (isInline) {
56	        return NextResponse.json({ text: mockInlineResponse(selection.text, instruction) });
57	      }
58	      return NextResponse.json({ content: mockWholeResponse(content, instruction) });
59	    }
60	
61	    if (isInline) {
62	      // Inline edit: return the replacement text (not necessarily valid JSON on its own)
63	      return NextResponse.json({ text: responseText });
64	    }
65	
66	    // Whole edit: validate that the response is valid JSON
67	    const cleaned = stripCodeFences(responseText);
68	    try {
69	      JSON.parse(cleaned);
70	      return NextResponse.json({ content: cleaned });
71	    } catch {
72	      // Try the raw response before giving up
73	      try {
74	        JSON.parse(responseText);
75	        return NextResponse.json({ content: responseText });
76	      } catch {
77	        // Log only length, not content — `responseText` is a function of the
78	        // user's source material and shouldn't end up in server logs.
79	        // The response payload still echoes a slice back to the caller, since
80	        // they originated the request and need it to debug their input.
81	        console.error(`[edit/artifact] LLM returned invalid JSON: ${responseText.length} chars`);
82	        return NextResponse.json(
83	          { error: "LLM response was not valid JSON", details: responseText.slice(0, 500) },
84	          { status: 502 },
85	        );
86	      }
87	    }
88	  } catch (err) {
89	    if (err instanceof OpenRouterError) {
90	      return NextResponse.json(
91	        { error: err.message, details: err.details },
92	        { status: 502 },
93	      );
94	    }
95	    const message = err instanceof Error ? err.message : "Unknown error";
96	    console.error("[edit/artifact] Unexpected error:", message);
97	    return NextResponse.json(
98	      { error: `LLM call failed: ${message}` },
99	      { status: 502 },
100	    );
101	  }
102	}
