28	  const decoder = new TextDecoder();
29	  let buffer = "";
30	  const events: Array<{ event: string; data: unknown }> = [];
31	
32	  for (;;) {
33	    const { done, value } = await reader.read();
34	    if (done) break;
35	    buffer += decoder.decode(value, { stream: true });
36	  }
37	
38	  const blocks = buffer.split("\n\n").filter(Boolean);
39	  for (const block of blocks) {
40	    let eventType = "";
41	    let dataStr = "";
42	    for (const line of block.split("\n")) {
43	      if (line.startsWith("event: ")) eventType = line.slice(7);
44	      else if (line.startsWith("data: ")) dataStr = line.slice(6);
45	    }
46	    if (eventType && dataStr) {
47	      events.push({ event: eventType, data: JSON.parse(dataStr) });
48	    }
49	  }
50	
51	  return events;
52	}
