61	export type CacheKey = {
62	  model: string;
63	  systemPrompt: string;
64	  userContent: string;
65	  maxTokens: number;
66	};
67	
68	type CallLlmResult = {
69	  text: string;
70	  usage: LlmCallUsage;
71	  cacheKey?: CacheKey;
72	};
