74	/** Record analytics and write to cache. Failures are silently ignored
75	 *  so they never break the LLM call that produced the result. */
76	async function recordAndCache(
77	  endpoint: string,
78	  usage: LlmCallUsage,
79	  text: string,
80	  cacheHash: string,
81	  cacheKey: CacheKey,
82	): Promise<CallLlmResult> {
83	  try {
84	    appendAnalyticsEntry({
85	      id: randomUUID(),
86	      endpoint,
87	      ...usage,
88	      timestamp: new Date().toISOString(),
89	    });
90	  } catch { /* persistence failure must not break LLM calls */ }
91	  const result: CallLlmResult = { text, usage, cacheKey };
92	  if (text) {
93	    try { await setCachedResult(cacheHash, result); } catch { /* cache write failure is non-fatal */ }
94	  }
95	  return result;
96	}
